/* 1024 * 2^(s/12): the knots the F-number is interpolated between */
static const unsigned short semi_tab[13] = {
 1024, 1085, 1149, 1218, 1290, 1367, 1448, 1534, 1625, 1722, 1825, 1933, 2048};

#define RG_KSC(r)    (alsa_lvl[(r)->lvl].ksc)
#define RG_PAN(r)    (alsa_lvl[(r)->lvl].pan)
#define RG_ATT(r)    (alsa_lvl[(r)->lvl].att)
#define RG_VF(r)     (alsa_lvl[(r)->lvl].vf)
#define RG_LFOVIB(r) (alsa_env[(r)->env].lfovib)
#define RG_AD1(r)    (alsa_env[(r)->env].ad1)
#define RG_LD2(r)    (alsa_env[(r)->env].ld2)
#define RG_RC(r)     (alsa_env[(r)->env].rc)
#define RG_TREM(r)   (alsa_env[(r)->env].trem)

/* p is 0..0x5FF, one octave in 100/128-cent units */
static unsigned pitch_fnum(unsigned p)
{
    unsigned s = p >> 7, f = p & 127;
    unsigned a = semi_tab[s], b = semi_tab[s + 1];
    return a + (((b - a) * f + 64) >> 7) - 1024;
}

